			for name, raw := range profiles {
				entry, _ := raw.(map[string]any)
				minPower, ok := intFromYAML(entry["min_power"])
				if !ok || minPower <= 0 {
					minPower = 1
				}
				maxPower, ok := intFromYAML(entry["max_power"])
				if !ok || maxPower <= 0 {
					maxPower = 10
				}
