package fizeau

import (
	"context"
	"time"

	"github.com/easel/fizeau/internal/routehealth"
)

const defaultRouteAttemptCooldown = routehealth.DefaultCooldown

func (s *service) RecordRouteAttempt(_ context.Context, attempt RouteAttempt) error {
	if s == nil {
		s = &service{}
	}
	return s.routeHealthStore().RecordAttempt(routehealth.Attempt{
		Harness:   attempt.Harness,
		Provider:  attempt.Provider,
		Model:     attempt.Model,
		Endpoint:  attempt.Endpoint,
		Status:    attempt.Status,
		Reason:    attempt.Reason,
		Error:     attempt.Error,
		Duration:  attempt.Duration,
		Timestamp: attempt.Timestamp,
	})
}

func (s *service) routeHealthStore() *routehealth.Store {
	if s.routeHealth == nil {
		s.routeHealth = routehealth.NewStore()
	}
	return s.routeHealth
}

func (s *service) activeRouteAttempts(now time.Time, ttl time.Duration) []routehealth.Record {
	if s == nil || s.routeHealth == nil {
		return nil
	}
	return s.routeHealth.ActiveAttempts(now, ttl)
}

func routeAttemptCooldown(record routehealth.Record, ttl time.Duration) *CooldownState {
	if ttl <= 0 {
		ttl = defaultRouteAttemptCooldown
	}
	reason := record.Reason
	if reason == "" {
		reason = "route_attempt_failure"
	}
	return &CooldownState{
		Reason:      reason,
		Until:       record.RecordedAt.Add(ttl),
		FailCount:   1,
		LastError:   record.Error,
		LastAttempt: record.RecordedAt,
	}
}

func (s *service) routeMetricSignals(now time.Time, ttl time.Duration) (map[string]float64, map[string]float64) {
	if s == nil || s.routeHealth == nil {
		return nil, nil
	}
	return s.routeHealth.MetricSignals(now, ttl)
}

func TestRouteStatus_RouteAttemptCooldownSurfaces(t *testing.T) {
	svc := routeAttemptTestService(t, 30*time.Second)
	recordedAt := time.Now().Add(-time.Second).UTC()
	if err := svc.RecordRouteAttempt(context.Background(), RouteAttempt{
		Harness:   "fiz",
		Provider:  "bragi",
		Model:     "qwen",
		Status:    "failed",
		Reason:    "rate_limit",
		Error:     "429 too many requests",
		Timestamp: recordedAt,
	}); err != nil {
		t.Fatalf("RecordRouteAttempt: %v", err)
	}

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	if len(report.Routes) != 1 {
		t.Fatalf("Routes: got %d, want 1", len(report.Routes))
	}
	byProvider := make(map[string]RouteCandidateStatus)
	for _, cand := range report.Routes[0].Candidates {
		byProvider[cand.Provider] = cand
	}
	bragi := byProvider["bragi"]
	if bragi.Healthy {
		t.Fatal("bragi should be unhealthy while route-attempt cooldown is active")
	}
	if bragi.Cooldown == nil {
		t.Fatal("bragi cooldown should be populated")
	}
	if bragi.Cooldown.Reason != "rate_limit" {
		t.Fatalf("Cooldown.Reason: got %q, want rate_limit", bragi.Cooldown.Reason)
	}
	if bragi.Cooldown.LastError != "429 too many requests" {
		t.Fatalf("Cooldown.LastError: got %q", bragi.Cooldown.LastError)
	}
	if !bragi.Cooldown.LastAttempt.Equal(recordedAt) {
		t.Fatalf("Cooldown.LastAttempt: got %s, want %s", bragi.Cooldown.LastAttempt, recordedAt)
	}
	if !byProvider["openrouter"].Healthy {
		t.Fatal("openrouter should remain healthy")
	}
}

