 15	// It is the operator dashboard view: cooldowns, recent decisions, and
 16	// per-candidate health. Distinct from per-request ResolveRoute.
 17	func (s *service) RouteStatus(ctx context.Context) (*RouteStatusReport, error) {
 18		s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
 19		report := &RouteStatusReport{
 20			GeneratedAt: time.Now(),
 21		}
 22		// ADR-006 §5: populate routing-quality over a recent window
 23		// (RouteStatusRoutingQualityWindow) regardless of whether a route
 24		// catalog is configured — the metric reflects Execute traffic, not
 25		// configured routes.
 26		if s != nil && s.routingQuality != nil {
 27			recent := s.routingQuality.snapshotRecent(RouteStatusRoutingQualityWindow, time.Time{})
 28			report.RoutingQuality = computeRoutingQualityMetricsFromRecords(recent)
 29		}
 30		if s == nil || s.opts.ServiceConfig == nil {
 31			return report, nil
 32		}
 33	
 34		cat := serviceRoutingCatalog()
 35		_, snapshot := s.buildRoutingInputsWithCatalog(ctx, cat)
 36		cooldown := s.routeAttemptTTL()
 37		activeAttempts := s.activeRouteAttempts(report.GeneratedAt, cooldown)
 38		successRate, latencyMS := s.routeMetricSignals(report.GeneratedAt, cooldown)
 39		report.Routes = s.routeStatusEntriesFromSnapshot(snapshot, activeAttempts, successRate, latencyMS, cooldown)
 40		return report, nil
