 43	func (s *service) routeStatusEntriesFromSnapshot(snapshot modelsnapshot.ModelSnapshot, activeAttempts []routehealth.Record, successRate, latencyMS map[string]float64, cooldown time.Duration) []RouteStatusEntry {
 44		if len(snapshot.Models) == 0 {
 45			return nil
 46		}
 47		grouped := make(map[string][]modelsnapshot.KnownModel)
 48		for _, row := range snapshot.Models {
 49			if harness := strings.TrimSpace(row.Harness); harness != "" && harness != "fiz" {
 50				continue
 51			}
 52			if s.opts.ServiceConfig != nil {
 53				if _, ok := s.opts.ServiceConfig.Provider(row.Provider); !ok {
 54					continue
 55				}
 56			}
 57			model := strings.TrimSpace(row.ID)
 58			if model == "" {
 59				continue
 60			}
 61			grouped[model] = append(grouped[model], row)
 62		}
 63		if len(grouped) == 0 {
 64			return nil
 65		}
 66		keys := make([]string, 0, len(grouped))
 67		for model := range grouped {
 68			keys = append(keys, model)
 69		}
 70		sort.Strings(keys)
 71	
 72		entries := make([]RouteStatusEntry, 0, len(keys))
 73		for _, model := range keys {
 74			rows := grouped[model]
 75			sort.Slice(rows, func(i, j int) bool {
 76				if rows[i].Provider != rows[j].Provider {
 77					return rows[i].Provider < rows[j].Provider
 78				}
 79				if rows[i].EndpointName != rows[j].EndpointName {
 80					return rows[i].EndpointName < rows[j].EndpointName
 81				}
 82				if rows[i].EndpointBaseURL != rows[j].EndpointBaseURL {
 83					return rows[i].EndpointBaseURL < rows[j].EndpointBaseURL
 84				}
 85				if rows[i].ServerInstance != rows[j].ServerInstance {
 86					return rows[i].ServerInstance < rows[j].ServerInstance
 87				}
 88				return rows[i].ID < rows[j].ID
 89			})
 90			entry := RouteStatusEntry{Model: model, Strategy: "auto"}
 91			if cached, ok := s.lookupRouteDecision(model); ok {
 92				entry.LastDecision = cached.decision
 93				entry.LastDecisionAt = cached.at
 94				entry.SelectedEndpoint = cached.decision.Endpoint
 95				entry.SelectedServerInstance = cached.decision.ServerInstance
 96				entry.Sticky = cached.decision.Sticky
 97			}
 98			entry.Candidates = make([]RouteCandidateStatus, 0, len(rows))
 99			for i, row := range rows {
100				provider := strings.TrimSpace(row.Provider)
101				endpoint := strings.TrimSpace(row.EndpointName)
102				serverID := serverinstance.Normalize(row.EndpointBaseURL, row.ServerInstance)
103				candidate := RouteCandidateStatus{
104					Provider:                provider,
105					Endpoint:                endpoint,
106					Model:                   model,
107					ServerInstance:          serverID,
108					Priority:                len(rows) - i,
109					Healthy:                 true,
110					SourceStatus:            string(row.Status),
111					AutoRoutable:            row.AutoRoutable,
112					ExactPinOnly:            row.ExactPinOnly,
113					ExclusionReason:         row.ExclusionReason,
114					Power:                   row.Power,
115					ContextLength:           row.ContextWindow,
116					CostInputPerMTok:        row.CostInputPerM,
117					CostOutputPerMTok:       row.CostOutputPerM,
118					RecentLatencyMS:         float64(row.RecentP50Latency.Milliseconds()),
119					ProviderReliabilityRate: routeStatusMetricValue(successRate, provider, endpoint, model),
120					QuotaRemaining:          row.QuotaRemaining,
121				}
122				if attemptCooldown := routeAttemptCandidateCooldown(activeAttempts, provider, endpoint, model, cooldown); attemptCooldown != nil {
123					candidate.Cooldown = attemptCooldown
124				}
125				if candidate.Cooldown != nil {
126					candidate.Healthy = false
127				}
128				if candidate.RecentLatencyMS == 0 {
129					candidate.RecentLatencyMS = routeStatusMetricValue(latencyMS, provider, endpoint, model)
130				}
131				entry.Candidates = append(entry.Candidates, candidate)
132			}
133			entries = append(entries, entry)
134		}
135		return entries
136	}
