138	func routeStatusMetricValue(values map[string]float64, provider, endpoint, model string) float64 {
139		if len(values) == 0 {
140			return 0
141		}
142		key := routeStatusMetricKey(provider, endpoint, model)
143		if value, ok := values[key]; ok {
144			return value
145		}
146		if endpoint != "" {
147			if value, ok := values[routeStatusMetricKey(provider, "", model)]; ok {
148				return value
149			}
150		}
151		return 0
152	}
