162	func routeAttemptCandidateCooldown(records []routehealth.Record, providerName, endpointName, model string, cooldown time.Duration) *CooldownState {
163		var newest *routehealth.Record
164		for i := range records {
165			record := &records[i]
166			if record.Key.Provider == "" {
167				continue
168			}
169			recordProvider := record.Key.Provider
170			recordEndpoint := record.Key.Endpoint
171			if base, ep, ok := splitEndpointProviderRef(recordProvider); ok {
172				recordProvider = base
173				if recordEndpoint == "" {
174					recordEndpoint = ep
175				}
176			}
177			if providerName != "" && recordProvider != providerName {
178				continue
179			}
180			if endpointName != "" && recordEndpoint != "" && recordEndpoint != endpointName {
181				continue
182			}
183			if record.Key.Model != "" && model != "" && record.Key.Model != model {
184				continue
185			}
186			if newest == nil || record.RecordedAt.After(newest.RecordedAt) {
187				newest = record
188			}
189		}
190		if newest == nil {
191			return nil
192		}
193		return routeAttemptCooldown(*newest, cooldown)
194	}
