 61		requestedPolicy := req.Policy
 62		policy := routingPolicyForName(cat, requestedPolicy)
 63		powerPolicy := routePowerPolicyForRequest(cat, req)
 64		providerPreference, err := providerPreferenceForPolicy(cat, requestedPolicy)
 65		if err != nil {
 66			return &RouteDecision{
 67				RequestedPolicy: req.Policy,
 68				PowerPolicy:     powerPolicy,
 69			}, err
 70		}
 71		in, snapshot := s.buildRoutingInputsWithCatalog(ctx, cat)
 72	
 73		resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
 74		if modelErr != nil {
 75			result := &RouteDecision{
 76				RequestedPolicy: req.Policy,
 77				PowerPolicy:     powerPolicy,
 78				Candidates:      modelCandidates,
 79			}
 80			s.annotateRouteDecisionEvidence(result)
 81			return result, publicRoutingError(modelErr, result.Candidates, req.Policy)
 82		}
 83	
 84		rReq := routing.Request{
 85			Policy:                policy,
 86			Model:                 resolvedModel,
 87			Provider:              req.Provider,
 88			Harness:               req.Harness,
 89			Reasoning:             effectiveReasoningString(req.Reasoning),
 90			Permissions:           req.Permissions,
 91			ProviderPreference:    providerPreference,
 92			EstimatedPromptTokens: req.EstimatedPromptTokens,
 93			RequiresTools:         req.RequiresTools,
 94			CorrelationID:         req.CorrelationID,
 95			AllowLocal:            req.AllowLocal,
 96			Require:               append([]string(nil), req.Require...),
 97		}
 98		if policyEntry, _, ok := policyForName(cat, requestedPolicy); ok {
 99			rReq.AllowLocal = rReq.AllowLocal || policyEntry.AllowLocal
100			rReq.Require = append(append([]string(nil), policyEntry.Require...), rReq.Require...)
101		}
102		rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
103		s.applyRouteAttemptCooldowns(&in)
104		dec, err := routing.Resolve(rReq, in)
105		if err != nil {
106			if escalated, edec, eerr := escalatePolicyLadder(rReq, in, err, req.Policy); escalated {
107				dec = edec
108				err = eerr
109			}
110		}
111		result := routeDecisionFromInternal(dec)
112		if err != nil {
113			if result == nil {
114				result = &RouteDecision{}
115			}
116			result.RequestedPolicy = req.Policy
117			result.PowerPolicy = powerPolicy
118			s.annotateRouteDecisionEvidence(result)
119			return result, publicRoutingError(err, result.Candidates, req.Policy)
120		}
121		s.applyStickyRouteLease(req.CorrelationID, result)
122		if result != nil && result.Endpoint == "" {
123			_, endpoint, _ := splitEndpointProviderRef(result.Provider)
124			result.Endpoint = endpoint
125		}
126		s.annotateRouteDecisionSnapshotEvidence(result, snapshot)
127		s.annotateRouteDecisionEvidence(result)
128		// Cache the decision so RouteStatus can surface LastDecision.
129		if result != nil {
130			result.RequestedPolicy = req.Policy
131			result.PowerPolicy = powerPolicy
132			result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
133			result.Power = catalogPowerForModel(cat, result.Model)
134		}
135		s.cacheRouteDecision(req.Model, result)
136		return result, nil
137	}
