139	func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
140		if dec == nil {
141			return nil
142		}
143		return &RouteDecision{
144			Harness:        dec.Harness,
145			Provider:       dec.Provider,
146			Endpoint:       dec.Endpoint,
147			ServerInstance: dec.ServerInstance,
148			Model:          dec.Model,
149			Reason:         dec.Reason,
150			Candidates:     routeCandidatesFromInternal(dec.Candidates),
151		}
152	}
