154	func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
155		if len(candidates) == 0 {
156			return nil
157		}
158		out := make([]RouteCandidate, len(candidates))
159		for i, candidate := range candidates {
160			out[i] = routeCandidateFromInternal(candidate)
161		}
162		return out
163	}
