746			}
747			if keys[i].EndpointBaseURL != keys[j].EndpointBaseURL {
748				return keys[i].EndpointBaseURL < keys[j].EndpointBaseURL
749			}
750			return keys[i].ServerInstance < keys[j].ServerInstance
751		})
752	
753		var entries []routing.ProviderEntry
754		for _, key := range keys {
755			pcfg, ok := s.opts.ServiceConfig.Provider(key.Provider)
756			if !ok || pcfg.ConfigError != "" {
757				continue
758			}
759			rows := append([]modelsnapshot.KnownModel(nil), grouped[key]...)
760			sort.Slice(rows, func(i, j int) bool {
