791				baseURL = pcfg.BaseURL
792			}
793			serverInstance := key.ServerInstance
794			if serverInstance == "" {
795				serverInstance = pcfg.ServerInstance
796			}
797			serverInstance = serverinstance.Normalize(baseURL, serverInstance)
798			entry := routing.ProviderEntry{
799				Name:                      routeName,
800				BaseURL:                   baseURL,
801				ServerInstance:            serverInstance,
802				EndpointName:              endpointName,
803				EndpointBaseURL:           baseURL,
804				DefaultModel:              pcfg.Model,
805				CostClass:                 providerRoutingCostClass(pcfg.Type),
806				DiscoveredIDs:             discoveredIDs,
807				DiscoveryAttempted:        true,
808				ContextWindows:            ctxWindows,
809				ContextWindowSources:      ctxSources,
810				ContextWindow:             pcfg.ContextWindow,
811				ContextWindowSource:       contextWindowSourceForProviderConfig(pcfg),
812				SupportsTools:             providerSupportsTools(cat, pcfg.Model, discoveredIDs),
813				ExcludeFromDefaultRouting: pcfg.IncludeByDefaultSet && !pcfg.IncludeByDefault,
814			}
815			s.applyEndpointRoutingCost(&entry, pcfg, cat)
816			entries = append(entries, entry)
817		}
818		return entries
819	}
